// Package telemetry reports anonymous installation usage.
package telemetry

import (
	"bytes"
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"net/http"
	"os"
	"path/filepath"
	"sync"
	"time"

	"github.com/gofrs/uuid"
	"github.com/markphelps/flipt/config"
	"github.com/sirupsen/logrus"
)

const (
	schemaVersion = "1.0"
	interval      = 4 * time.Hour
	stateFile     = "telemetry.json"
)

// Version is set by the executable to the version of the running Flipt build.
var Version = "dev"

// endpoint is the Flipt telemetry intake. It receives only the JSON event below.
var endpoint = "https://telemetry.flipt.io/v1/track"

type state struct {
	Version       string `json:"version"`
	UUID          string `json:"uuid"`
	LastTimestamp string `json:"lastTimestamp"`
}

// Reporter persists a host identifier and reports usage in the background.
type Reporter struct {
	mu     sync.Mutex
	state  state
	path   string
	logger logrus.FieldLogger
	client *http.Client
}

// NewReporter initializes telemetry if it is enabled. A failed initialization
// is returned to the caller so it can log the error and continue serving.
func NewReporter(cfg *config.Config, logger logrus.FieldLogger) (*Reporter, error) {
	if cfg == nil || !cfg.Meta.TelemetryEnabled {
		return nil, nil
	}
	if logger == nil {
		logger = logrus.StandardLogger()
	}
	dir := cfg.Meta.StateDirectory
	if dir == "" {
		var err error
		dir, err = os.UserConfigDir()
		if err != nil {
			return nil, fmt.Errorf("finding telemetry state directory: %w", err)
		}
	}
	if err := os.MkdirAll(dir, 0700); err != nil {
		return nil, fmt.Errorf("creating telemetry state directory: %w", err)
	}
	r := &Reporter{path: filepath.Join(dir, stateFile), logger: logger, client: &http.Client{Timeout: 10 * time.Second}}
	data, err := os.ReadFile(r.path)
	if err != nil && !errors.Is(err, os.ErrNotExist) {
		return nil, fmt.Errorf("reading telemetry state: %w", err)
	}
	if err == nil {
		if err = json.Unmarshal(data, &r.state); err != nil {
			logger.Warnf("reading telemetry state: %v", err)
		}
	}
	if _, err = uuid.FromString(r.state.UUID); err != nil {
		id, genErr := uuid.NewV4()
		if genErr != nil {
			return nil, fmt.Errorf("generating telemetry UUID: %w", genErr)
		}
		r.state.UUID = id.String()
	}
	r.state.Version = schemaVersion
	if _, err := time.Parse(time.RFC3339, r.state.LastTimestamp); err != nil {
		r.state.LastTimestamp = time.Now().UTC().Format(time.RFC3339)
	}
	if err := r.save(); err != nil {
		return nil, err
	}
	return r, nil
}

func (r *Reporter) save() error {
	data, err := json.Marshal(r.state)
	if err != nil {
		return fmt.Errorf("encoding telemetry state: %w", err)
	}
	f, err := os.CreateTemp(filepath.Dir(r.path), ".telemetry-*")
	if err != nil {
		return fmt.Errorf("creating telemetry state: %w", err)
	}
	defer os.Remove(f.Name())
	if err := f.Chmod(0600); err != nil {
		f.Close()
		return fmt.Errorf("setting telemetry state permissions: %w", err)
	}
	if _, err := f.Write(data); err != nil {
		f.Close()
		return fmt.Errorf("writing telemetry state: %w", err)
	}
	if err := f.Close(); err != nil {
		return fmt.Errorf("closing telemetry state: %w", err)
	}
	if err := os.Rename(f.Name(), r.path); err != nil {
		return fmt.Errorf("saving telemetry state: %w", err)
	}
	return nil
}

// Start launches a loop that sends a ping immediately and every four hours.
func (r *Reporter) Start(ctx context.Context) {
	if r == nil {
		return
	}
	go func() {
		if ctx.Err() == nil {
			if err := r.Report(ctx); err != nil {
				r.logger.Warnf("reporting telemetry: %v", err)
			}
		}
		ticker := time.NewTicker(interval)
		defer ticker.Stop()
		for {
			select {
			case <-ctx.Done():
				return
			case <-ticker.C:
				if err := r.Report(ctx); err != nil {
					r.logger.Warnf("reporting telemetry: %v", err)
				}
			}
		}
	}()
}

// Report sends one anonymous ping and updates the timestamp on success.
func (r *Reporter) Report(ctx context.Context) error {
	if r == nil {
		return nil
	}
	r.mu.Lock()
	defer r.mu.Unlock()
	payload := struct {
		AnonymousId string                 `json:"anonymousId"`
		Event       string                 `json:"event"`
		Properties  map[string]interface{} `json:"properties"`
	}{
		AnonymousId: r.state.UUID,
		Event:       "flipt.ping",
		Properties: map[string]interface{}{
			"uuid":          r.state.UUID,
			"version":       schemaVersion,
			"flipt.version": Version,
		},
	}
	body, err := json.Marshal(payload)
	if err != nil {
		return fmt.Errorf("encoding telemetry event: %w", err)
	}
	req, err := http.NewRequestWithContext(ctx, http.MethodPost, endpoint, bytes.NewReader(body))
	if err != nil {
		return fmt.Errorf("creating telemetry request: %w", err)
	}
	req.Header.Set("Content-Type", "application/json")
	resp, err := r.client.Do(req)
	if err != nil {
		return fmt.Errorf("sending telemetry: %w", err)
	}
	defer resp.Body.Close()
	_, _ = io.Copy(io.Discard, resp.Body)
	if resp.StatusCode < 200 || resp.StatusCode >= 300 {
		return fmt.Errorf("sending telemetry: HTTP %d", resp.StatusCode)
	}
	r.state.LastTimestamp = time.Now().UTC().Format(time.RFC3339)
	return r.save()
}
